    private func assetName(toggled: Bool, filled: Bool) -> String {
        let state = toggled && Self.assets["\(rawValue)|on|false"] != nil ? "on" : "normal"
        return Self.assets["\(rawValue)|\(state)|\(filled)"]
            ?? Self.assets["\(rawValue)|\(state)|false"]!
    }

    /// Fixed 1.5-point stroke at a 20-point base size. Optional fills are baked opaque.
    public func uiImage(toggled: Bool = false, filled: Bool = false) -> UIImage {
        let name = assetName(toggled: toggled, filled: filled)
        guard let image = UIImage(named: name, in: Self.bundle, compatibleWith: nil) else {
            preconditionFailure("Missing Slice icon asset: \(name)")
        }
        return image.withRenderingMode(.alwaysTemplate)
    }

    public func image(toggled: Bool = false, filled: Bool = false) -> Image {
        Image(uiImage: uiImage(toggled: toggled, filled: filled)).renderingMode(.template)
    }
